-- =============================================================================
-- University of Nigeria, Nsukka - Faculty of Science - Mathematics
-- Course outlines transcribed from the departmental course handbook.
-- =============================================================================
-- Run in the Supabase SQL Editor. Safe to run more than once: existing rows
-- for these courses are removed first, so it updates rather than duplicates.
--
-- NOTE ON SEMESTERS: the handbook does not state which semester each course
-- runs in. The values below follow the usual Nigerian convention that an odd
-- final digit is first semester and an even one is second -- which lines up
-- neatly with the paired courses here (Abstract Algebra I/II, Linear Algebra
-- I/II, Complex Analysis I/II and so on). Correct any that differ at UNN by
-- editing the semester column in the Table Editor.
--
-- Mathematical notation is written in LaTeX between dollar signs and renders
-- as proper notation inside the app.
-- =============================================================================

delete from public.course_outlines
 where institution = 'University of Nigeria, Nsukka'
   and department = 'Mathematics';

insert into public.course_outlines
  (course_code, course_title, institution, faculty, department, level,
   semester, credit_units, description, topics, contributor_name)
values
  ('MTH 111', 'Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Science', 'Mathematics', '100 Level', 'first', 3, 'Elementary Set theory, subsets, union, intersection, complements. Venn diagrams, Real numbers, integers, rational and irrational numbers, mathematical induction, real sequences and series, theory of quadratic equations, binomial theorem. Circular measure, trigonometric functions of angles of any magnitude, addition and factor formulae. Complex numbers, algebra of complex numbers, the Argand Diagram, De Moivre''s theorem, $n$th roots of unity.', '["Elementary Set theory, subsets, union, intersection, complements", "Venn diagrams, Real numbers, integers, rational and irrational numbers, mathematical induction, real sequences and series, theory of quadratic equations, binomial theorem", "Circular measure, trigonometric functions of angles of any magnitude, addition and factor formulae", "Complex numbers, algebra of complex numbers, the Argand Diagram, De Moivre''s theorem, $n$th roots of unity"]'::jsonb, 'Department of Mathematics handbook'),
  ('MTH 121', 'Elementary Mathematics II', 'University of Nigeria, Nsukka', 'Faculty of Science', 'Mathematics', '100 Level', 'first', 3, 'Functions of a real variable, graphs, limits and continuity. The derivative as limit of rate of change. Techniques of differentiation. Curve sketching, integration as an inverse of differentiation. Methods of integration, definite integrals. Application of integration to areas and volumes.', '["Functions of a real variable, graphs, limits and continuity", "The derivative as limit of rate of change", "Techniques of differentiation", "Curve sketching, integration as an inverse of differentiation", "Methods of integration, definite integrals", "Application of integration to areas and volumes"]'::jsonb, 'Department of Mathematics handbook'),
  ('MTH 122', 'Elementary Mathematics III', 'University of Nigeria, Nsukka', 'Faculty of Science', 'Mathematics', '100 Level', 'second', 3, 'Geometric representation of vectors in 1-3 dimensions, Components, direction cosines. Addition of vectors and multiplication of vectors by a scalar, linear independence. Scalar and vector products of two vectors. Differentiation and integration of vectors with respect to a scalar variable. Two-dimensional coordinate geometry. Straight lines, circles, parabolas, ellipses, hyperbolas. Tangents and normals. Kinematics of a particle. Components of velocity and acceleration of a particle moving in a plane. Force and momentum. Newton''s laws of motion; motion under gravity, projectile motion, resisted vertical motion of a particle, elastic string, motion of a simple pendulum, impulse and impact of momentum. Impact of two smooth elastic spheres. Direct and oblique impacts.', '["Geometric representation of vectors in 1-3 dimensions, Components, direction cosines", "Addition of vectors and multiplication of vectors by a scalar, linear independence", "Scalar and vector products of two vectors", "Differentiation and integration of vectors with respect to a scalar variable", "Two-dimensional coordinate geometry", "Straight lines, circles, parabolas, ellipses, hyperbolas", "Tangents and normals", "Kinematics of a particle", "Components of velocity and acceleration of a particle moving in a plane", "Force and momentum", "Newton''s laws of motion", "Motion under gravity, projectile motion, resisted vertical motion of a particle, elastic string, motion of a simple pendulum, impulse and impact of momentum", "Impact of two smooth elastic spheres", "Direct and oblique impacts"]'::jsonb, 'Department of Mathematics handbook'),
  ('MTH 132', 'Elementary Mechanics I', 'University of Nigeria, Nsukka', 'Faculty of Science', 'Mathematics', '100 Level', 'second', 3, 'Vectors: Algebra of vectors; coplanar forces; their resolution into components, equilibrium conditions, moments and couples, parallel forces; friction; centroids and centres of gravity of particles and rigid bodies; equivalence of sets of coplanar forces. Kinematics and rectilinear motion of a particle, vertical motion under gravity, projection, relative motion. Dynamics of a particle. Newton''s laws of motion; motion of connected particles.', '["Vectors: Algebra of vectors", "Coplanar forces", "Their resolution into components, equilibrium conditions, moments and couples, parallel forces", "Friction", "Centroids and centres of gravity of particles and rigid bodies", "Equivalence of sets of coplanar forces", "Kinematics and rectilinear motion of a particle, vertical motion under gravity, projection, relative motion", "Dynamics of a particle", "Newton''s laws of motion", "Motion of connected particles"]'::jsonb, 'Department of Mathematics handbook'),
  ('MTH 201', 'Advanced Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Science', 'Mathematics', '200 Level', 'first', 3, 'Mathematics and symbolic logic: inductive and deductive systems. Concepts of sets; mappings and transformations. Introduction to complex numbers. Introduction to vectors, matrices and determinants.', '["Mathematics and symbolic logic: inductive and deductive systems", "Concepts of sets", "Mappings and transformations", "Introduction to complex numbers", "Introduction to vectors, matrices and determinants"]'::jsonb, 'Department of Mathematics handbook'),
  ('MTH 202', 'Advanced Mathematics II', 'University of Nigeria, Nsukka', 'Faculty of Science', 'Mathematics', '200 Level', 'second', 3, 'Discrete and continuous variables. The equation of a straight line in various forms. Trigonometric functions; logarithmic functions; exponential functions. Maxima, minima and points of inflexion. Integral Calculus: Integration by substitution and by parts. Expansion of algebraic functions. Simple sequences and series.', '["Discrete and continuous variables", "The equation of a straight line in various forms", "Trigonometric functions", "Logarithmic functions", "Exponential functions", "Maxima, minima and points of inflexion", "Integral Calculus: Integration by substitution and by parts", "Expansion of algebraic functions", "Simple sequences and series"]'::jsonb, 'Department of Mathematics handbook'),
  ('MTH 203', 'Advanced Mathematics III', 'University of Nigeria, Nsukka', 'Faculty of Science', 'Mathematics', '200 Level', 'first', 3, 'Matrices and determinants, introduction to linear programming and integer programming.', '["Matrices and determinants, introduction to linear programming and integer programming"]'::jsonb, 'Department of Mathematics handbook'),
  ('MTH 205', 'Advanced Mathematics V', 'University of Nigeria, Nsukka', 'Faculty of Science', 'Mathematics', '200 Level', 'first', 3, 'Translation and rotation of axes, plane geometry of lines, circles and other simple curves, lines in space; equations of the plane, space curve. The Gaussian and mean curvatures, the geodesic and geodesic curvature.', '["Translation and rotation of axes, plane geometry of lines, circles and other simple curves, lines in space", "Equations of the plane, space curve", "The Gaussian and mean curvatures, the geodesic and geodesic curvature"]'::jsonb, 'Department of Mathematics handbook'),
  ('MTH 206', 'Advanced Mathematics VI', 'University of Nigeria, Nsukka', 'Faculty of Science', 'Mathematics', '200 Level', 'second', 2, 'Complex analysis - Elements of the algebra of complex variables, trigonometric, exponential and logarithmic functions. The number system, sequences and series. Vector differentiation and integration.', '["Complex analysis - Elements of the algebra of complex variables, trigonometric, exponential and logarithmic functions", "The number system, sequences and series", "Vector differentiation and integration"]'::jsonb, 'Department of Mathematics handbook'),
  ('MTH 207', 'Advanced Mathematics VII', 'University of Nigeria, Nsukka', 'Faculty of Science', 'Mathematics', '200 Level', 'first', 2, 'Elements of linear algebra. Calculus: Elementary differentiation and relevant theorems. Differential equations: Exact equations, methods of solution of second-order ordinary differential equations, partial differential equations, with applications.', '["Elements of linear algebra", "Calculus: Elementary differentiation and relevant theorems", "Differential equations: Exact equations, methods of solution of second-order ordinary differential equations, partial differential equations, with applications"]'::jsonb, 'Department of Mathematics handbook'),
  ('MTH 208', 'Advanced Mathematics VIII', 'University of Nigeria, Nsukka', 'Faculty of Science', 'Mathematics', '200 Level', 'second', 2, 'Numerical analysis: Linear equations, non-linear equations; finite difference operators. Introduction to linear programming.', '["Numerical analysis: Linear equations, non-linear equations", "Finite difference operators", "Introduction to linear programming"]'::jsonb, 'Department of Mathematics handbook'),
  ('MTH 211', 'Sets, Logic and Algebra', 'University of Nigeria, Nsukka', 'Faculty of Science', 'Mathematics', '200 Level', 'first', 3, 'Introduction to the language and concepts of modern mathematics; topics include: Basic set theory, mappings, relations, equivalence and other relations, Cartesian product. Binary logic, methods of proof. Binary operations, algebraic structures, semi-groups, rings, integral domains, fields, Homomorphism. Number systems; properties of integers, rationals, real and complex numbers.', '["Introduction to the language and concepts of modern mathematics", "Topics include: Basic set theory, mappings, relations, equivalence and other relations, Cartesian product", "Binary logic, methods of proof", "Binary operations, algebraic structures, semi-groups, rings, integral domains, fields, Homomorphism", "Number systems", "Properties of integers, rationals, real and complex numbers"]'::jsonb, 'Department of Mathematics handbook'),
  ('MTH 215', 'Linear Algebra I', 'University of Nigeria, Nsukka', 'Faculty of Science', 'Mathematics', '200 Level', 'first', 2, 'System of linear equations. Matrices and algebra of matrices. Vector spaces over the real field. Subspaces, linear independence, bases and dimensions. Gram-Schmidt orthogonalization procedure. Linear transformations: range, null space and rank. Singular and non-singular transformations.', '["System of linear equations", "Matrices and algebra of matrices", "Vector spaces over the real field", "Subspaces, linear independence, bases and dimensions", "Gram-Schmidt orthogonalization procedure", "Linear transformations: range, null space and rank", "Singular and non-singular transformations"]'::jsonb, 'Department of Mathematics handbook'),
  ('MTH 216', 'Linear Algebra II', 'University of Nigeria, Nsukka', 'Faculty of Science', 'Mathematics', '200 Level', 'second', 2, 'Representations of linear transformations by matrices, change of bases, equivalence and similarity. Determinants. Eigenvalues and eigenvectors. Minimum and characteristic polynomials of a linear transformation. Cayley-Hamilton theorem, bilinear and quadratic forms, orthogonal diagonalization. Canonical forms.', '["Representations of linear transformations by matrices, change of bases, equivalence and similarity", "Determinants", "Eigenvalues and eigenvectors", "Minimum and characteristic polynomials of a linear transformation", "Cayley-Hamilton theorem, bilinear and quadratic forms, orthogonal diagonalization", "Canonical forms"]'::jsonb, 'Department of Mathematics handbook'),
  ('MTH 218', 'Three-Dimensional Analytic Geometry', 'University of Nigeria, Nsukka', 'Faculty of Science', 'Mathematics', '200 Level', 'second', 2, 'Plane curves, parametric representations, length of a plane arc, lines in three-space, surfaces, cylinders, cylindrical and spherical coordinates, quadratic forms, quadrics and central quadrics.', '["Plane curves, parametric representations, length of a plane arc, lines in three-space, surfaces, cylinders, cylindrical and spherical coordinates, quadratic forms, quadrics and central quadrics"]'::jsonb, 'Department of Mathematics handbook'),
  ('MTH 221', 'Real Analysis I', 'University of Nigeria, Nsukka', 'Faculty of Science', 'Mathematics', '200 Level', 'first', 3, 'Bounds of real numbers, convergence of sequences of numbers. Monotone convergence of series. Absolute and conditional convergence of series, and rearrangements. Completeness of reals and incompleteness of rationals. Continuity and differentiability of functions. Rolle''s and mean-value theorems for differentiable functions. Taylor series.', '["Bounds of real numbers, convergence of sequences of numbers", "Monotone convergence of series", "Absolute and conditional convergence of series, and rearrangements", "Completeness of reals and incompleteness of rationals", "Continuity and differentiability of functions", "Rolle''s and mean-value theorems for differentiable functions", "Taylor series"]'::jsonb, 'Department of Mathematics handbook'),
  ('MTH 222', 'Elementary Differential Equations I', 'University of Nigeria, Nsukka', 'Faculty of Science', 'Mathematics', '200 Level', 'second', 3, 'First-order ordinary differential equations. Existence and uniqueness of solution. Second-order ordinary differential equations with constant coefficients. General theory of $n$th-order linear ordinary differential equations. The Laplace transform. Solution of initial- and boundary-value problems by Laplace transform method. Simple treatment of partial differential equations in two independent variables. Applications of ordinary and partial differential equations to physical, life and engineering problems.', '["First-order ordinary differential equations", "Existence and uniqueness of solution", "Second-order ordinary differential equations with constant coefficients", "General theory of $n$th-order linear ordinary differential equations", "The Laplace transform", "Solution of initial- and boundary-value problems by Laplace transform method", "Simple treatment of partial differential equations in two independent variables", "Applications of ordinary and partial differential equations to physical, life and engineering problems"]'::jsonb, 'Department of Mathematics handbook'),
  ('MTH 224', 'Introduction to Numerical Analysis', 'University of Nigeria, Nsukka', 'Faculty of Science', 'Mathematics', '200 Level', 'second', 3, 'Solution of algebraic and transcendental equations. Curve fitting, error analysis. Interpolation, approximation, zeros of non-linear equations of one variable. Systems of linear equations. Numerical differentiation and integration. Numerical solution of initial-value problems for ordinary differential equations.', '["Solution of algebraic and transcendental equations", "Curve fitting, error analysis", "Interpolation, approximation, zeros of non-linear equations of one variable", "Systems of linear equations", "Numerical differentiation and integration", "Numerical solution of initial-value problems for ordinary differential equations"]'::jsonb, 'Department of Mathematics handbook'),
  ('MTH 231', 'Elementary Mechanics II', 'University of Nigeria, Nsukka', 'Faculty of Science', 'Mathematics', '200 Level', 'first', 2, 'Impulse and Momentum, conservation of momentum, work, power and energy; work and energy principle, conservation of mechanical energy. Direct and oblique impact of elastic bodies. General motion of a particle in two dimensions, central orbits, motion in horizontal and vertical circles, simple harmonic motion, motion of a particle attached to a light inelastic spring or string. Motion of a rigid body about a fixed axis; moments of inertia calculations; perpendicular and parallel axes theorems, principal axes of inertia and direction. Conservation of energy. Compound pendulum. Conservation of angular momentum.', '["Impulse and Momentum, conservation of momentum, work, power and energy", "Work and energy principle, conservation of mechanical energy", "Direct and oblique impact of elastic bodies", "General motion of a particle in two dimensions, central orbits, motion in horizontal and vertical circles, simple harmonic motion, motion of a particle attached to a light inelastic spring or string", "Motion of a rigid body about a fixed axis", "Moments of inertia calculations", "Perpendicular and parallel axes theorems, principal axes of inertia and direction", "Conservation of energy", "Compound pendulum", "Conservation of angular momentum"]'::jsonb, 'Department of Mathematics handbook'),
  ('MTH 242', 'Mathematical Methods I', 'University of Nigeria, Nsukka', 'Faculty of Science', 'Mathematics', '200 Level', 'second', 3, 'Real-valued functions of a real variable. Review of differentiation and integration and their applications. Mean-value theorem. Taylor series. Real-valued functions of two or three variables. Partial derivatives. Chain-rule, extrema, Lagrange''s multipliers, increments, differentials and linear approximations. Evaluation of line-integrals. Multiple integrals.', '["Real-valued functions of a real variable", "Review of differentiation and integration and their applications", "Mean-value theorem", "Taylor series", "Real-valued functions of two or three variables", "Partial derivatives", "Chain-rule, extrema, Lagrange''s multipliers, increments, differentials and linear approximations", "Evaluation of line-integrals", "Multiple integrals"]'::jsonb, 'Department of Mathematics handbook'),
  ('MTH 311', 'Abstract Algebra I', 'University of Nigeria, Nsukka', 'Faculty of Science', 'Mathematics', '300 Level', 'first', 3, 'Group: definition; examples, including permutation groups. Subgroups and cosets. Lagrange''s theorem and applications. Cyclic groups. Normal subgroups and quotient groups. Homomorphism. Isomorphism theorems. Cayley''s theorems. Direct products. Groups of small order. Group acting on sets. Sylow theorems.', '["Group: definition", "Examples, including permutation groups", "Subgroups and cosets", "Lagrange''s theorem and applications", "Cyclic groups", "Normal subgroups and quotient groups", "Homomorphism", "Isomorphism theorems", "Cayley''s theorems", "Direct products", "Groups of small order", "Group acting on sets", "Sylow theorems"]'::jsonb, 'Department of Mathematics handbook'),
  ('MTH 312', 'Abstract Algebra II', 'University of Nigeria, Nsukka', 'Faculty of Science', 'Mathematics', '300 Level', 'second', 3, 'Rings: definition; examples, including $\mathbb{Z}$, $\mathbb{Z}_n$; rings of polynomials and matrices, integral domains, fields, polynomial rings, factorization. Euclidean algorithm for polynomials, H.C.F. and L.C.M. of polynomials. Ideals and quotient rings, P.I.D.''s, U.F.D''s, Euclidean rings. Irreducibility. Field theorems, degree of an extension, minimum polynomial. Algebraic and transcendental extensions. Straight-edge and compass constructions.', '["Rings: definition", "Examples, including $\\mathbb{Z}$, $\\mathbb{Z}_n$", "Rings of polynomials and matrices, integral domains, fields, polynomial rings, factorization", "Euclidean algorithm for polynomials, H.C.F", "And L.C.M", "Of polynomials", "Ideals and quotient rings, P.I.D.''s, U.F.D''s, Euclidean rings", "Irreducibility", "Field theorems, degree of an extension, minimum polynomial", "Algebraic and transcendental extensions", "Straight-edge and compass constructions"]'::jsonb, 'Department of Mathematics handbook'),
  ('MTH 313', 'Geometry I', 'University of Nigeria, Nsukka', 'Faculty of Science', 'Mathematics', '300 Level', 'first', 2, 'Coordinates in 3-space. Polar coordinates; distance between points, surfaces and curves in space. The plane and straight line.', '["Coordinates in 3-space", "Polar coordinates", "Distance between points, surfaces and curves in space", "The plane and straight line"]'::jsonb, 'Department of Mathematics handbook'),
  ('MTH 314', 'Geometry II', 'University of Nigeria, Nsukka', 'Faculty of Science', 'Mathematics', '300 Level', 'second', 2, 'Introductory projective geometry. Affine and Euclidean geometries.', '["Introductory projective geometry", "Affine and Euclidean geometries"]'::jsonb, 'Department of Mathematics handbook'),
  ('MTH 316', 'Differential Geometry', 'University of Nigeria, Nsukka', 'Faculty of Science', 'Mathematics', '300 Level', 'second', 3, 'Concept of a curve, regular, differentiable and smooth curves, osculating, rectifying and normal planes, tangent lines, curvature, torsion, Frenet-Serret formulae, fundamental, existence and uniqueness theorem, involutes, evolutes, spherical indicatrix, developable surfaces, ruled surfaces, curves on a surface, first and second fundamental forms, lines of curvature, umbilics, asymptotic curves, geodesics. Topological properties of simple surfaces.', '["Concept of a curve, regular, differentiable and smooth curves, osculating, rectifying and normal planes, tangent lines, curvature, torsion, Frenet-Serret formulae, fundamental, existence and uniqueness theorem, involutes, evolutes, spherical indicatrix, developable surfaces, ruled surfaces, curves on a surface, first and second fundamental forms, lines of curvature, umbilics, asymptotic curves, geodesics", "Topological properties of simple surfaces"]'::jsonb, 'Department of Mathematics handbook'),
  ('MTH 321', 'Metric Space Topology', 'University of Nigeria, Nsukka', 'Faculty of Science', 'Mathematics', '300 Level', 'first', 3, 'Sets, metrics and examples. Open spheres or balls. Open sets and neighbourhoods. Closed sets. Interior, exterior, frontier, limit points and closure of a set. Dense subsets and separable space. Convergence in metric space, homeomorphism. Continuity and compactness, connectedness.', '["Sets, metrics and examples", "Open spheres or balls", "Open sets and neighbourhoods", "Closed sets", "Interior, exterior, frontier, limit points and closure of a set", "Dense subsets and separable space", "Convergence in metric space, homeomorphism", "Continuity and compactness, connectedness"]'::jsonb, 'Department of Mathematics handbook'),
  ('MTH 322', 'Elements of Differential Equations II', 'University of Nigeria, Nsukka', 'Faculty of Science', 'Mathematics', '300 Level', 'second', 3, 'Series solution of second-order differential equations. Sturm-Liouville problems. Orthogonal polynomials and functions. Fourier series, Fourier-Bessel and Fourier-Legendre series. Fourier transformation, solution of Laplace, wave and heat equations by the Fourier method (separation of variables). Special functions: Gamma, Beta, Bessel, Legendre and Hypergeometric.', '["Series solution of second-order differential equations", "Sturm-Liouville problems", "Orthogonal polynomials and functions", "Fourier series, Fourier-Bessel and Fourier-Legendre series", "Fourier transformation, solution of Laplace, wave and heat equations by the Fourier method (separation of variables)", "Special functions: Gamma, Beta, Bessel, Legendre and Hypergeometric"]'::jsonb, 'Department of Mathematics handbook'),
  ('MTH 323', 'Complex Analysis I', 'University of Nigeria, Nsukka', 'Faculty of Science', 'Mathematics', '300 Level', 'first', 3, 'Functions of a complex variable: limits and continuity of functions of a complex variable. Derivation of the Cauchy-Riemann equations; Bilinear transformations, conformal mapping, contour integrals. Cauchy''s theorem and its main consequences. Convergence of sequences and series of functions of a complex variable. Power series. Taylor series.', '["Functions of a complex variable: limits and continuity of functions of a complex variable", "Derivation of the Cauchy-Riemann equations", "Bilinear transformations, conformal mapping, contour integrals", "Cauchy''s theorem and its main consequences", "Convergence of sequences and series of functions of a complex variable", "Power series", "Taylor series"]'::jsonb, 'Department of Mathematics handbook'),
  ('MTH 324', 'Vector and Tensor Analysis', 'University of Nigeria, Nsukka', 'Faculty of Science', 'Mathematics', '300 Level', 'second', 3, 'Vector algebra. The dot and cross products. Equations of curves and surfaces. Vector differentiation and applications. Gradient, divergence and curl. Vector integrals: line, surface and volume integrals. Green''s, Stoke''s and divergence theorems. Tensor products of vector spaces. Tensor algebra. Symmetry. Cartesian tensors and applications.', '["Vector algebra", "The dot and cross products", "Equations of curves and surfaces", "Vector differentiation and applications", "Gradient, divergence and curl", "Vector integrals: line, surface and volume integrals", "Green''s, Stoke''s and divergence theorems", "Tensor products of vector spaces", "Tensor algebra", "Symmetry", "Cartesian tensors and applications"]'::jsonb, 'Department of Mathematics handbook'),
  ('MTH 326', 'Real Analysis II', 'University of Nigeria, Nsukka', 'Faculty of Science', 'Mathematics', '300 Level', 'second', 3, 'Riemann integral of real function of a real variable, continuous monopositive functions. Functions of bounded variation. The Riemann-Stieltjes integral. Point-wise and uniform convergence of sequences and series of functions. Effects on limits (sums) when the functions are continuously differentiable or Riemann integrable power series.', '["Riemann integral of real function of a real variable, continuous monopositive functions", "Functions of bounded variation", "The Riemann-Stieltjes integral", "Point-wise and uniform convergence of sequences and series of functions", "Effects on limits (sums) when the functions are continuously differentiable or Riemann integrable power series"]'::jsonb, 'Department of Mathematics handbook'),
  ('MTH 328', 'Complex Analysis II', 'University of Nigeria, Nsukka', 'Faculty of Science', 'Mathematics', '300 Level', 'second', 3, 'Laurent expansions, isolated singularities and residues. The Residue theorem, calculus of residues and application to the evaluation of integrals and to summation of series. Maximum modulus principle. Argument principle. Rouche''s theorem. The fundamental theorem of algebra. Principle of analytic continuation. Multiple-valued functions and Riemann surfaces.', '["Laurent expansions, isolated singularities and residues", "The Residue theorem, calculus of residues and application to the evaluation of integrals and to summation of series", "Maximum modulus principle", "Argument principle", "Rouche''s theorem", "The fundamental theorem of algebra", "Principle of analytic continuation", "Multiple-valued functions and Riemann surfaces"]'::jsonb, 'Department of Mathematics handbook'),
  ('MTH 331', 'Introduction to Mathematical Modelling', 'University of Nigeria, Nsukka', 'Faculty of Science', 'Mathematics', '300 Level', 'first', 3, 'Methodology of model building; identification, formulation and solution of problems; cause-effect diagrams. Equation types. Algebraic, ordinary differential, partial differential, difference, integral and functional equations. Applications of mathematical models to physical, biological, social and behavioural sciences.', '["Methodology of model building", "Identification, formulation and solution of problems", "Cause-effect diagrams", "Equation types", "Algebraic, ordinary differential, partial differential, difference, integral and functional equations", "Applications of mathematical models to physical, biological, social and behavioural sciences"]'::jsonb, 'Department of Mathematics handbook'),
  ('MTH 334', 'Special Theory of Relativity', 'University of Nigeria, Nsukka', 'Faculty of Science', 'Mathematics', '300 Level', 'second', 4, 'Classical mechanics and principles of Relativity, Einstein Postulates; Interval between events, Lorentz transformation and its consequences; Four-Dimensional Space-time, Relativistic Mechanics of particle, Maxwell''s theory in a Relativistic form. Optical phenomena.', '["Classical mechanics and principles of Relativity, Einstein Postulates", "Interval between events, Lorentz transformation and its consequences", "Four-Dimensional Space-time, Relativistic Mechanics of particle, Maxwell''s theory in a Relativistic form", "Optical phenomena"]'::jsonb, 'Department of Mathematics handbook'),
  ('MTH 336', 'Dynamics of a Rigid Body', 'University of Nigeria, Nsukka', 'Faculty of Science', 'Mathematics', '300 Level', 'second', 3, 'General motion of a rigid body as a translation plus a rotation. Moment of inertia and product of inertia in three dimensions. Parallel and perpendicular axes theorems. Principal axes, angular momentum, kinetic energy of a rigid body. Impulsive motion. Examples involving one- and two-dimensional motion of a simple systems. Moving frames of reference; rotating and translating frames of reference. Coriolis force. Motion near the earth''s surface. The Foucault''s pendulum. Euler''s dynamical equations of motion of a rigid body with one point fixed. The symmetric top. Precessional motion.', '["General motion of a rigid body as a translation plus a rotation", "Moment of inertia and product of inertia in three dimensions", "Parallel and perpendicular axes theorems", "Principal axes, angular momentum, kinetic energy of a rigid body", "Impulsive motion", "Examples involving one- and two-dimensional motion of a simple systems", "Moving frames of reference", "Rotating and translating frames of reference", "Coriolis force", "Motion near the earth''s surface", "The Foucault''s pendulum", "Euler''s dynamical equations of motion of a rigid body with one point fixed", "The symmetric top", "Precessional motion"]'::jsonb, 'Department of Mathematics handbook'),
  ('MTH 337', 'Optimization Theory I', 'University of Nigeria, Nsukka', 'Faculty of Science', 'Mathematics', '300 Level', 'first', 2, 'Linear programming models. The simplex method: formulation and theory, duality, integer programming; transportation problem. Two-person-zero-sum games. Nonlinear programming. Quadratic programming.', '["Linear programming models", "The simplex method: formulation and theory, duality, integer programming", "Transportation problem", "Two-person-zero-sum games", "Nonlinear programming", "Quadratic programming"]'::jsonb, 'Department of Mathematics handbook'),
  ('MTH 338', 'Optimization Theory II', 'University of Nigeria, Nsukka', 'Faculty of Science', 'Mathematics', '300 Level', 'second', 2, 'Kuhn-Tucker methods. Optimality criteria. Single variable optimization. Multivariable techniques. Gradient methods.', '["Kuhn-Tucker methods", "Optimality criteria", "Single variable optimization", "Multivariable techniques", "Gradient methods"]'::jsonb, 'Department of Mathematics handbook'),
  ('MTH 339', 'Analytic Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Science', 'Mathematics', '300 Level', 'first', 3, 'Degrees of freedom. Holonomic and non-holonomic constraints. Generalized coordinates. Lagrange''s equations of motion for holonomic systems; force dependent on coordinates only; force obtainable from a potential. Impulsive force.', '["Degrees of freedom", "Holonomic and non-holonomic constraints", "Generalized coordinates", "Lagrange''s equations of motion for holonomic systems", "Force dependent on coordinates only", "Force obtainable from a potential", "Impulsive force"]'::jsonb, 'Department of Mathematics handbook'),
  ('MTH 341', 'Discrete Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Science', 'Mathematics', '300 Level', 'first', 2, 'Groups and subgroups, group axioms, permutation groups, cosets, graphs, directed and undirected graphs, subgraphs, cycles, connectivity. Applications (flow charts) and state-transition graphs.', '["Groups and subgroups, group axioms, permutation groups, cosets, graphs, directed and undirected graphs, subgraphs, cycles, connectivity", "Applications (flow charts) and state-transition graphs"]'::jsonb, 'Department of Mathematics handbook'),
  ('MTH 342', 'Discrete Mathematics II', 'University of Nigeria, Nsukka', 'Faculty of Science', 'Mathematics', '300 Level', 'second', 2, 'Lattices and Boolean algebra. Finite fields: Mini-polynomials, irreducible polynomials, polynomial roots. Applications (error-correcting codes).', '["Lattices and Boolean algebra", "Finite fields: Mini-polynomials, irreducible polynomials, polynomial roots", "Applications (error-correcting codes)"]'::jsonb, 'Department of Mathematics handbook'),
  ('MTH 344', 'Numerical Analysis I', 'University of Nigeria, Nsukka', 'Faculty of Science', 'Mathematics', '300 Level', 'second', 3, 'Polynomials and splines approximation. Orthogonal polynomial and Chebyshev approximation. Direct and iterative methods for the solution of system of linear equations. Eigenvalue problem - power methods, inverse power method, pivoting strategies.', '["Polynomials and splines approximation", "Orthogonal polynomial and Chebyshev approximation", "Direct and iterative methods for the solution of system of linear equations", "Eigenvalue problem - power methods, inverse power method, pivoting strategies"]'::jsonb, 'Department of Mathematics handbook'),
  ('MTH 412', 'Abstract Algebra III', 'University of Nigeria, Nsukka', 'Faculty of Science', 'Mathematics', '400 Level', 'second', 3, 'Splitting fields. Separability. Algebraic closure. Solvable groups. Fundamental theorem of Galois theory. Solution by radicals. Definition and examples of modules, submodules and quotient modules. Isomorphism theorems. Theory of group representations.', '["Splitting fields", "Separability", "Algebraic closure", "Solvable groups", "Fundamental theorem of Galois theory", "Solution by radicals", "Definition and examples of modules, submodules and quotient modules", "Isomorphism theorems", "Theory of group representations"]'::jsonb, 'Department of Mathematics handbook'),
  ('MTH 421', 'Ordinary Differential Equations', 'University of Nigeria, Nsukka', 'Faculty of Science', 'Mathematics', '400 Level', 'first', 3, 'Existence and uniqueness of solutions; dependence on initial conditions and on parameters, general theory for linear differential equations with constant coefficients. The two-point Sturm-Liouville boundary value problem; self-adjointness; Sturm theory; stability of solutions of nonlinear equations; phase-plane analysis. Floquet Theory. Integral equations classifications - Volterra and Fredholm types. Reduction of ordinary differential equations to integral equations.', '["Existence and uniqueness of solutions", "Dependence on initial conditions and on parameters, general theory for linear differential equations with constant coefficients", "The two-point Sturm-Liouville boundary value problem", "Self-adjointness", "Sturm theory", "Stability of solutions of nonlinear equations", "Phase-plane analysis", "Floquet Theory", "Integral equations classifications - Volterra and Fredholm types", "Reduction of ordinary differential equations to integral equations"]'::jsonb, 'Department of Mathematics handbook'),
  ('MTH 424', 'General Topology', 'University of Nigeria, Nsukka', 'Faculty of Science', 'Mathematics', '400 Level', 'second', 3, 'Topological spaces, definition, open and closed sets, neighbourhood. Coarser and finer topologies. Bases and sub-bases. Separation axioms, compactness, local compactness, connectedness. Construction of new topological spaces from given ones. Subspaces, quotient spaces, continuous functions, homomorphisms, topological invariants, spaces of continuous functions. Point-wise and uniform convergence.', '["Topological spaces, definition, open and closed sets, neighbourhood", "Coarser and finer topologies", "Bases and sub-bases", "Separation axioms, compactness, local compactness, connectedness", "Construction of new topological spaces from given ones", "Subspaces, quotient spaces, continuous functions, homomorphisms, topological invariants, spaces of continuous functions", "Point-wise and uniform convergence"]'::jsonb, 'Department of Mathematics handbook'),
  ('MTH 425', 'Lebesgue Measure and Integration', 'University of Nigeria, Nsukka', 'Faculty of Science', 'Mathematics', '400 Level', 'first', 3, 'Lebesgue measure: measurable and non-measurable sets. Measurable functions. Lebesgue integral: integration of non-negative functions, the general integral convergence theorems.', '["Lebesgue measure: measurable and non-measurable sets", "Measurable functions", "Lebesgue integral: integration of non-negative functions, the general integral convergence theorems"]'::jsonb, 'Department of Mathematics handbook'),
  ('MTH 426', 'Measure Theory', 'University of Nigeria, Nsukka', 'Faculty of Science', 'Mathematics', '400 Level', 'second', 4, 'Abstract $L^p$-spaces.', '["Abstract $L^p$-spaces"]'::jsonb, 'Department of Mathematics handbook'),
  ('MTH 427', 'Field Theory in Mathematical Physics', 'University of Nigeria, Nsukka', 'Faculty of Science', 'Mathematics', '400 Level', 'first', 3, 'Gradient, divergence and curl. Further treatment and application of the definitions of the differential: The integral definition of gradient, divergence and curl. Line-, surface- and volume-integrals. Green''s, Gauss''s, and Stokes'' theorems. Curvilinear coordinates. Simple notion of tensors. The use of tensor notations.', '["Gradient, divergence and curl", "Further treatment and application of the definitions of the differential: The integral definition of gradient, divergence and curl", "Line-, surface- and volume-integrals", "Green''s, Gauss''s, and Stokes'' theorems", "Curvilinear coordinates", "Simple notion of tensors", "The use of tensor notations"]'::jsonb, 'Department of Mathematics handbook'),
  ('MTH 428', 'Partial Differential Equations', 'University of Nigeria, Nsukka', 'Faculty of Science', 'Mathematics', '400 Level', 'second', 3, 'Partial differential equations in two independent variables with constant coefficients: the Cauchy problem for the quasi-linear first-order partial differential equations in two independent variables; existence and uniqueness of solutions. The Cauchy problem for the linear, second-order partial differential equation in two independent variables, existence and uniqueness of solution: normal forms. Boundary- and initial-value problems for hyperbolic, elliptic and parabolic partial differential equations.', '["Partial differential equations in two independent variables with constant coefficients: the Cauchy problem for the quasi-linear first-order partial differential equations in two independent variables", "Existence and uniqueness of solutions", "The Cauchy problem for the linear, second-order partial differential equation in two independent variables, existence and uniqueness of solution: normal forms", "Boundary- and initial-value problems for hyperbolic, elliptic and parabolic partial differential equations"]'::jsonb, 'Department of Mathematics handbook'),
  ('MTH 429', 'Functional Analysis', 'University of Nigeria, Nsukka', 'Faculty of Science', 'Mathematics', '400 Level', 'first', 3, 'A survey of the classical theory of metric spaces, including Baire''s category theorem, compactness, separability, isometries and completion. Elements of Banach and Hilbert spaces; parallelogram law and polar identity in Hilbert space $H$; the natural embeddings of normed linear spaces into second dual, and $H$ onto $H$; properties of operators including the open mapping and closed graph theorem; the spaces $C(X)$, the sequence (Banach) spaces $\ell_p^n$, $\ell_p$ and $c$ (space of convergent sequences).', '["A survey of the classical theory of metric spaces, including Baire''s category theorem, compactness, separability, isometries and completion", "Elements of Banach and Hilbert spaces", "Parallelogram law and polar identity in Hilbert space $H$", "The natural embeddings of normed linear spaces into second dual, and $H$ onto $H$", "Properties of operators including the open mapping and closed graph theorem", "The spaces $C(X)$, the sequence (Banach) spaces $\\ell_p^n$, $\\ell_p$ and $c$ (space of convergent sequences)"]'::jsonb, 'Department of Mathematics handbook'),
  ('MTH 432', 'General Theory of Relativity', 'University of Nigeria, Nsukka', 'Faculty of Science', 'Mathematics', '400 Level', 'second', 3, 'Particles in a gravitational field: Curvilinear coordinates, intervals. Covariant differentiation: Christoffel symbols and metric tensor. The constant gravitational field. Rotation. The curvature tensor. The action function for the gravitational field. The energy-momentum tensor. Newton''s laws. Motion in a centrally symmetric gravitational field. The energy-momentum pseudo-tensor. Gravitational waves. Gravitational fields at large distances from bodies. Isotropic space. Space-time metric in the closed and open isotropic models.', '["Particles in a gravitational field: Curvilinear coordinates, intervals", "Covariant differentiation: Christoffel symbols and metric tensor", "The constant gravitational field", "Rotation", "The curvature tensor", "The action function for the gravitational field", "The energy-momentum tensor", "Newton''s laws", "Motion in a centrally symmetric gravitational field", "The energy-momentum pseudo-tensor", "Gravitational waves", "Gravitational fields at large distances from bodies", "Isotropic space", "Space-time metric in the closed and open isotropic models"]'::jsonb, 'Department of Mathematics handbook'),
  ('MTH 434', 'Elasticity', 'University of Nigeria, Nsukka', 'Faculty of Science', 'Mathematics', '400 Level', 'second', 3, 'Stress and strain analysis, constitutive relations, equilibrium and compatibility equations, principles of minimum potential and complementary energy, principles of virtual work, variational formulation, extension, bending and torsion of beams; elastic waves.', '["Stress and strain analysis, constitutive relations, equilibrium and compatibility equations, principles of minimum potential and complementary energy, principles of virtual work, variational formulation, extension, bending and torsion of beams", "Elastic waves"]'::jsonb, 'Department of Mathematics handbook'),
  ('MTH 436', 'Fluid Dynamics', 'University of Nigeria, Nsukka', 'Faculty of Science', 'Mathematics', '400 Level', 'second', 3, 'Real and ideal fluids; differentiation following the motion of fluid particles. Equations of motion and continuity for incompressible inviscid fluids. Velocity potentials and Stokes'' stream function. Bernoulli''s equation with applications to flows along curved paths. Kinetic energy. Sources, sinks and doublets in 2- and 3-dimensional flows; limiting stream lines. Images and rigid planes, streaming motion past bodies including aerofoils.', '["Real and ideal fluids", "Differentiation following the motion of fluid particles", "Equations of motion and continuity for incompressible inviscid fluids", "Velocity potentials and Stokes'' stream function", "Bernoulli''s equation with applications to flows along curved paths", "Kinetic energy", "Sources, sinks and doublets in 2- and 3-dimensional flows", "Limiting stream lines", "Images and rigid planes, streaming motion past bodies including aerofoils"]'::jsonb, 'Department of Mathematics handbook'),
  ('MTH 437', 'Systems Theory', 'University of Nigeria, Nsukka', 'Faculty of Science', 'Mathematics', '400 Level', 'first', 4, 'Existence, boundedness and periodicity for solutions of linear systems of differential equations with constant coefficients. Lyapunov theorems. Solution of Lyapunov stability equations $A^{T}P + PA = C$. Controllability and observability. Theorems on existence of solution of linear systems of different equations with constant coefficients.', '["Existence, boundedness and periodicity for solutions of linear systems of differential equations with constant coefficients", "Lyapunov theorems", "Solution of Lyapunov stability equations $A^{T}P + PA = C$", "Controllability and observability", "Theorems on existence of solution of linear systems of different equations with constant coefficients"]'::jsonb, 'Department of Mathematics handbook'),
  ('MTH 438', 'Electromagnetism', 'University of Nigeria, Nsukka', 'Faculty of Science', 'Mathematics', '400 Level', 'second', 3, 'Maxwell''s field equations. Electromagnetic waves and electromagnetic theory of light; plane electromagnetic waves in non-conducting media; reflected and refractional place-boundary. Wave-guides and resonant cavities. Simple radiating systems. The Lorentz-Einstein transformation. Energy and momentum. Electromagnetic 4-vectors. Transformation of $(E, H)$ fields. The Lorentz force.', '["Maxwell''s field equations", "Electromagnetic waves and electromagnetic theory of light", "Plane electromagnetic waves in non-conducting media", "Reflected and refractional place-boundary", "Wave-guides and resonant cavities", "Simple radiating systems", "The Lorentz-Einstein transformation", "Energy and momentum", "Electromagnetic 4-vectors", "Transformation of $(E, H)$ fields", "The Lorentz force"]'::jsonb, 'Department of Mathematics handbook'),
  ('MTH 439', 'Analytical Dynamics II', 'University of Nigeria, Nsukka', 'Faculty of Science', 'Mathematics', '400 Level', 'first', 3, 'Lagrange''s equations for non-holonomic systems. Lagrange''s multipliers. Variational principles. Calculus of variations. Hamilton''s principle. Lagrange''s equations of motion from Hamilton''s principle. Contact or canonical transformations. Normal modes of vibration. Hamilton-Jacobi equations for a dynamical system.', '["Lagrange''s equations for non-holonomic systems", "Lagrange''s multipliers", "Variational principles", "Calculus of variations", "Hamilton''s principle", "Lagrange''s equations of motion from Hamilton''s principle", "Contact or canonical transformations", "Normal modes of vibration", "Hamilton-Jacobi equations for a dynamical system"]'::jsonb, 'Department of Mathematics handbook'),
  ('MTH 441', 'Mathematical Method II', 'University of Nigeria, Nsukka', 'Faculty of Science', 'Mathematics', '400 Level', 'first', 3, 'Calculus of variations: Lagrange''s functional and associated density. Necessary condition for a weak relative extremum. Hamilton''s principle. Lagrange''s equations and geodesic problems. The Du Bois Raymond equation and corner conditions. Variable end points and related theorems. Sufficient conditions for a minimum, isoperimetric problems. Variational integral transforms. Laplace, Fourier and Hankel transforms. Complex variable methods; convolution theorems; applications to solutions of differential equations with initial/boundary conditions.', '["Calculus of variations: Lagrange''s functional and associated density", "Necessary condition for a weak relative extremum", "Hamilton''s principle", "Lagrange''s equations and geodesic problems", "The Du Bois Raymond equation and corner conditions", "Variable end points and related theorems", "Sufficient conditions for a minimum, isoperimetric problems", "Variational integral transforms", "Laplace, Fourier and Hankel transforms", "Complex variable methods", "Convolution theorems", "Applications to solutions of differential equations with initial/boundary conditions"]'::jsonb, 'Department of Mathematics handbook');
